solution.solution.cpp:
#include <algorithm>
#include <cctype>
#include <cstdint>
#include <deque>
#include <map>
#include <optional>
#include <string>
#include <vector>

struct Out { int client; std::string line; };

class ChatServer
{
public:
    int connect()
    {
        clients[next] = {};
        return next++;
    }

    std::vector<Out> receive(int client, const std::string& line, std::uint64_t nowMs)
    {
        const auto it{ clients.find(client) };
        if (it == clients.end()) return {};
        Client& c{ it->second };
        std::vector<Out> out;
        const auto reply = [&](const std::string& text) { out.push_back({ client, text }); };

        while (!c.recent.empty() && c.recent.front() + 1000 <= nowMs) c.recent.pop_front();
        const bool limited{ c.recent.size() >= 5 };
        c.recent.push_back(nowMs);
        if (line.size() > 512) { reply("ERROR line too long"); return out; }
        if (limited) { reply("ERROR slow down"); return out; }

        const std::size_t space{ line.find(' ') };
        const std::string command{ line.substr(0, space) };
        const std::string rest{ space == std::string::npos ? "" : line.substr(space + 1) };

        if (command == "QUIT")
        {
            reply("BYE");
            for (const Out& o : leave(client)) out.push_back(o);
            return out;
        }
        if (command == "HELLO")
        {
            if (c.name) { reply("ERROR already joined"); return out; }
            const std::size_t gap{ rest.find(' ') };
            const std::string version{ rest.substr(0, gap) };
            const std::string name{ gap == std::string::npos ? "" : rest.substr(gap + 1) };
            if (version != "1") { reply("ERROR unsupported version"); clients.erase(client); return out; }
            if (!validName(name)) { reply("ERROR bad name"); return out; }
            if (findUser(name)) { reply("ERROR name taken"); return out; }
            c.name = name;
            reply("WELCOME " + name);
            toOthers(out, client, "JOINED " + name);
            return out;
        }
        if (command != "SAY" && command != "TELL" && command != "WHO") { reply("ERROR unknown command " + command); return out; }
        if (!c.name) { reply("ERROR say hello first"); return out; }
        if (command == "WHO")
        {
            std::string list;
            for (const std::string& n : users()) list += (list.empty() ? "" : ",") + n;
            reply("USERS " + list);
        }
        else if (command == "SAY")
        {
            if (rest.empty()) reply("ERROR empty message");
            else if (rest.size() > 200) reply("ERROR message too long");
            else toOthers(out, client, "FROM " + *c.name + " " + rest);
        }
        else
        {
            const std::size_t gap{ rest.find(' ') };
            if (gap == std::string::npos || gap + 1 >= rest.size()) { reply("ERROR usage: TELL name text"); return out; }
            const std::string target{ rest.substr(0, gap) };
            const auto who{ findUser(target) };
            if (!who) { reply("ERROR no such user " + target); return out; }
            out.push_back({ *who, "PRIVATE " + *c.name + " " + rest.substr(gap + 1) });
        }
        return out;
    }

    std::vector<Out> disconnect(int client)
    {
        if (!clients.count(client)) return {};
        return leave(client);
    }

    std::vector<std::string> users() const
    {
        std::vector<std::string> names;
        for (const auto& [id, c] : clients) if (c.name) names.push_back(*c.name);
        std::sort(names.begin(), names.end(), [](const std::string& a, const std::string& b) { return lower(a) < lower(b); });
        return names;
    }

private:
    struct Client { std::optional<std::string> name; std::deque<std::uint64_t> recent; };
    std::map<int, Client> clients;
    int next{ 1 };

    static std::string lower(std::string s)
    {
        for (char& ch : s) ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
        return s;
    }

    static bool validName(const std::string& n)
    {
        if (n.empty() || n.size() > 16) return false;
        for (char ch : n) if (!std::isalnum(static_cast<unsigned char>(ch)) && ch != '_' && ch != '-') return false;
        return true;
    }

    std::optional<int> findUser(const std::string& name) const
    {
        for (const auto& [id, c] : clients) if (c.name && lower(*c.name) == lower(name)) return id;
        return std::nullopt;
    }

    void toOthers(std::vector<Out>& out, int sender, const std::string& line) const
    {
        for (const auto& [id, c] : clients) if (id != sender && c.name) out.push_back({ id, line });
    }

    std::vector<Out> leave(int client)
    {
        std::vector<Out> out;
        const auto name{ clients[client].name };
        clients.erase(client);
        if (name) for (const auto& [id, c] : clients) if (c.name) out.push_back({ id, "LEFT " + *name });
        return out;
    }
};

unitTests:
using Lines = std::vector<Out>;
static bool same(const Lines& got, std::initializer_list<Out> want)
{
    if (got.size() != want.size()) return false;
    std::size_t i{ 0 };
    for (const Out& w : want) { if (got[i].client != w.client || got[i].line != w.line) return false; ++i; }
    return true;
}

TEST("joining") {
    ChatServer s;
    const int a{ s.connect() }, b{ s.connect() };
    CHECK(same(s.receive(a, "HELLO 1 Ada", 0), { { a, "WELCOME Ada" } }));
    CHECK(same(s.receive(b, "HELLO 1 Bob", 10), { { b, "WELCOME Bob" }, { a, "JOINED Bob" } }));
    CHECK_EQ(s.users(), (std::vector<std::string>{ "Ada", "Bob" }));
    CHECK(same(s.receive(a, "HELLO 1 Ada", 20), { { a, "ERROR already joined" } }));
}
TEST("handshake errors") {
    ChatServer s;
    const int a{ s.connect() }, b{ s.connect() }, c{ s.connect() };
    s.receive(a, "HELLO 1 ada", 0);
    CHECK(same(s.receive(b, "HELLO 1 ADA", 0), { { b, "ERROR name taken" } }));
    CHECK(same(s.receive(b, "HELLO 1 bad name!", 0), { { b, "ERROR bad name" } }));
    CHECK(same(s.receive(b, "HELLO 1 " + std::string(17, 'x'), 0), { { b, "ERROR bad name" } }));
    CHECK(same(s.receive(b, "SAY hi", 0), { { b, "ERROR say hello first" } }));
    CHECK(same(s.receive(c, "HELLO 2 Cy", 0), { { c, "ERROR unsupported version" } }));
    CHECK(s.receive(c, "HELLO 1 Cy", 0).empty());
}
TEST("messages") {
    ChatServer s;
    const int a{ s.connect() }, b{ s.connect() }, c{ s.connect() };
    s.receive(a, "HELLO 1 Ada", 0); s.receive(b, "HELLO 1 bob", 0); s.receive(c, "HELLO 1 Cy", 0);
    CHECK(same(s.receive(a, "SAY hello there", 100), { { b, "FROM Ada hello there" }, { c, "FROM Ada hello there" } }));
    CHECK(same(s.receive(b, "TELL ada see you", 200), { { a, "PRIVATE bob see you" } }));
    CHECK(same(s.receive(b, "TELL dan hi", 300), { { b, "ERROR no such user dan" } }));
    CHECK(same(s.receive(b, "TELL ada", 400), { { b, "ERROR usage: TELL name text" } }));
    CHECK(same(s.receive(c, "WHO", 500), { { c, "USERS Ada,bob,Cy" } }));
    CHECK(same(s.receive(c, "SAY", 600), { { c, "ERROR empty message" } }));
    CHECK(same(s.receive(c, "SAY " + std::string(201, 'x'), 700), { { c, "ERROR message too long" } }));
    CHECK(same(s.receive(c, "DANCE", 800), { { c, "ERROR unknown command DANCE" } }));
}
TEST("rate limits and long lines") {
    ChatServer s;
    const int a{ s.connect() }, b{ s.connect() };
    s.receive(a, "HELLO 1 Ada", 0);
    s.receive(b, "HELLO 1 Bob", 0);
    for (int i{ 1 }; i <= 4; ++i) CHECK_EQ(s.receive(a, "SAY " + std::to_string(i), 100 + i).size(), 1u);
    CHECK(same(s.receive(a, "SAY 5", 106), { { a, "ERROR slow down" } }));
    CHECK(same(s.receive(a, "SAY 6", 1001), { { a, "ERROR slow down" } }));
    CHECK(same(s.receive(a, "SAY 7", 1106), { { b, "FROM Ada 7" } }));
    CHECK(same(s.receive(b, std::string(513, 'x'), 2000), { { b, "ERROR line too long" } }));
}
TEST("leaving") {
    ChatServer s;
    const int a{ s.connect() }, b{ s.connect() }, c{ s.connect() };
    s.receive(a, "HELLO 1 Ada", 0); s.receive(b, "HELLO 1 Bob", 0);
    CHECK(same(s.receive(a, "QUIT", 10), { { a, "BYE" }, { b, "LEFT Ada" } }));
    CHECK(s.receive(a, "WHO", 20).empty());
    CHECK(same(s.disconnect(b), {}));
    CHECK(s.users().empty());
    CHECK(same(s.receive(c, "QUIT", 30), { { c, "BYE" } }));
    CHECK(s.disconnect(c).empty());
    const int d{ s.connect() }, e{ s.connect() };
    s.receive(d, "HELLO 1 Dee", 40); s.receive(e, "HELLO 1 Eve", 40);
    CHECK(same(s.disconnect(d), { { e, "LEFT Dee" } }));
}

